// Process all content and prepare for database
const outline = JSON.parse($('OpenAI - Create Outline (GPT-3.5)').first().json.choices[0].message.content);
const finalContent = $('OpenAI - Polish Content (GPT-4)').first().json.choices[0].message.content;
const seoData = JSON.parse($('OpenAI - SEO Optimization (GPT-3.5)').first().json.choices[0].message.content);
const imageData = $('OpenAI - Generate Featured Image (DALL-E 3)').first().json;
const contentPlan = $('Supabase - Get Content Plan').first().json;

// Calculate total cost
const outlineTokens = $('OpenAI - Create Outline (GPT-3.5)').first().json.usage.total_tokens;
const draftTokens = $('OpenAI - Write Draft (GPT-3.5)').first().json.usage.total_tokens;
const polishTokens = $('OpenAI - Polish Content (GPT-4)').first().json.usage.total_tokens;
const seoTokens = $('OpenAI - SEO Optimization (GPT-3.5)').first().json.usage.total_tokens;

// Cost calculation (approximate)
const gpt35Cost = (outlineTokens + draftTokens + seoTokens) * 0.0015 / 1000; // GPT-3.5 cost
const gpt4Cost = polishTokens * 0.03 / 1000; // GPT-4 cost
const imageCost = 0.080; // DALL-E 3 cost
const totalCost = gpt35Cost + gpt4Cost + imageCost;

// Generate excerpt (first 160 characters of content)
const excerpt = finalContent.substring(0, 160).replace(/\s+$/, '') + '...';

// Create slug from title
const slug = seoData.slug || outline.title.toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .substring(0, 60);

return {
  json: {
    title: outline.title,
    slug: slug,
    content: finalContent,
    excerpt: excerpt,
    meta_title: seoData.meta_title,
    meta_description: seoData.meta_description,
    featured_image_url: imageData.data[0].url,
    featured_image_alt: seoData.featured_image_alt,
    status: 'draft',
    category: contentPlan.content_type,
    tags: contentPlan.keywords || [],
    seo_keywords: seoData.focus_keyphrases || contentPlan.keywords,
    internal_links: seoData.internal_links || [],
    ai_generation_cost: Math.round(totalCost * 100) / 100,
    content_plan_id: contentPlan.id,
    outline_data: outline,
    token_usage: {
      outline: outlineTokens,
      draft: draftTokens,
      polish: polishTokens,
      seo: seoTokens,
      total: outlineTokens + draftTokens + polishTokens + seoTokens
    }
  }
};
